"use client";
import {useEffect,useState} from "react";
import {AlertTriangle,CheckCircle2,ChevronRight} from "lucide-react";
import PageTitle from "@/composants/ui/PageTitle";
import Section from "@/composants/ui/Section";
import Input from "@/composants/ui/Input";
import Select from "@/composants/ui/Select";
import Textarea from "@/composants/ui/Textarea";
import Alert from "@/composants/ui/Alert";
import serviceSignalement from "@/services/ServiceSignalement.js";

const statusStyle={ouvert:"bg-rose-50 text-rose-800",en_traitement:"bg-amber-50 text-amber-900",escalade:"bg-violet-50 text-violet-800",resolu:"bg-indigo-50 text-indigo-800",rejete:"bg-slate-200 text-slate-800"};
export default function SignalementsPanel({origin="Commerçant",manager=false,superManager=false}){
 const [items,setItems]=useState([]); const [page,setPage]=useState(1); const [pagination,setPagination]=useState({page:1,total:0,hasNext:false}); const [filters,setFilters]=useState({status:"",type:"",search:""}); const [form,setForm]=useState({type:"autre",deliveryRef:"",description:"",priority:"normale"}); const [message,setMessage]=useState(null);
 async function refresh(){const r=await serviceSignalement.getAll({...filters,page,limit:10});setItems(r.data||[]);setPagination(r.pagination||{});} useEffect(()=>{refresh();},[page,filters.status,filters.type]);
 async function create(){if(!form.description.trim()){setMessage({type:"error",message:"Décrivez le problème avant d'envoyer le signalement."});return;} await serviceSignalement.create({...form,origin});setForm({type:"autre",deliveryRef:"",description:"",priority:"normale"});setMessage({type:"success",message:"Signalement enregistré."});await refresh();}
 async function act(id,status){
   try{
     setMessage(null);
     await serviceSignalement.update(id,status,status==="escalade"?"Dossier transmis pour arbitrage.":"Décision enregistrée.");
     setMessage({type:"success",message:status==="escalade"?"Le signalement a été transmis pour arbitrage.":"La décision a été enregistrée."});
     await refresh();
   }catch(error){
     setMessage({type:"error",message:error?.message||"Impossible de traiter ce signalement."});
   }
 }
 const visible=superManager?items.filter(i=>i.status==="escalade"):manager?items.filter(i=>i.type!=="probleme_paiement"):items.filter(i=>i.origin===origin);
 return <div className="space-y-8"><PageTitle title={manager?"Signalements":superManager?"Arbitrages escaladés":"Mes signalements"} description={manager?"Traitez les problèmes remontés dans votre périmètre.":superManager?"Arbitrez les dossiers transmis par les managers.":"Déclarez un problème et suivez son traitement."}/><Section title="Filtres"><div className="grid gap-3 md:grid-cols-[1fr_220px_220px_auto]"><input value={filters.search} onChange={e=>setFilters({...filters,search:e.target.value})} placeholder="Référence ou description" className="h-11 rounded-xl border border-slate-200 bg-white px-4 text-sm text-slate-900"/><select value={filters.status} onChange={e=>{setPage(1);setFilters({...filters,status:e.target.value})}} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900"><option value="">Tous les statuts</option><option value="ouvert">Ouverts</option><option value="en_traitement">En traitement</option><option value="escalade">Escaladés</option><option value="resolu">Résolus</option><option value="rejete">Rejetés</option></select><select value={filters.type} onChange={e=>{setPage(1);setFilters({...filters,type:e.target.value})}} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900"><option value="">Tous les types</option><option value="probleme_reception_livreur">Réception/livreur</option><option value="probleme_livraison_client">Livraison/client</option><option value="probleme_paiement">Paiement</option><option value="autre">Autre</option></select><button onClick={()=>{setPage(1);refresh()}} className="rounded-xl bg-indigo-600 px-5 text-sm font-bold text-white">Rechercher</button></div></Section>{message&&<Alert type={message.type} message={message.message}/>} {!manager&&!superManager&&<Section title="Nouveau signalement"><div className="grid gap-5 md:grid-cols-2"><Select label="Type" name="type" value={form.type} onChange={e=>setForm({...form,type:e.target.value})}><option value="autre">Autre problème</option>{origin==="Point relais"&&<><option value="probleme_reception_livreur">Problème avec un livreur</option><option value="probleme_livraison_client">Problème avec un client</option></>}{origin==="Commerçant"&&<option value="probleme_paiement">Problème de paiement</option>}</Select><Input label="Référence livraison (optionnelle)" name="deliveryRef" value={form.deliveryRef} onChange={e=>setForm({...form,deliveryRef:e.target.value})} placeholder="LIV-00001"/><Select label="Priorité" name="priority" value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="normale">Normale</option><option value="haute">Haute</option></Select></div><div className="mt-5"><Textarea label="Description" name="description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Expliquez précisément le problème..."/></div><button onClick={create} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white hover:bg-indigo-700"><AlertTriangle size={17}/> Envoyer</button></Section>}
 <Section title={`${visible.length} dossier(s)`}><div className="space-y-3">{visible.length===0?<p className="text-sm text-slate-600">Aucun signalement à afficher.</p>:visible.map(item=><article key={item.id} className="rounded-2xl border border-slate-200 bg-slate-50 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-black text-slate-900">Signalement #{item.id}</p><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${statusStyle[item.status]||statusStyle.ouvert}`}>{item.status.replaceAll("_"," ")}</span>{item.priority==="haute"&&<span className="rounded-full bg-rose-500/10 px-2.5 py-1 text-[11px] font-bold text-rose-700">Prioritaire</span>}</div><p className="mt-2 text-xs text-slate-600">{item.origin} · {item.deliveryRef||"Sans livraison"} · {new Date(item.createdAt).toLocaleDateString("fr-FR")}</p></div><ChevronRight size={18} className="text-slate-600"/></div><p className="mt-4 text-sm leading-6 text-slate-700">{item.description}</p>{(manager||superManager)&&!["resolu","rejete"].includes(item.status)&&<div className="mt-4 flex flex-wrap gap-2"><button onClick={()=>act(item.id,"resolu")} className="inline-flex items-center gap-2 rounded-lg bg-indigo-600 px-3 py-2 text-xs font-bold text-white"><CheckCircle2 size={14}/> Résoudre</button><button onClick={()=>act(item.id,"rejete")} className="rounded-lg border border-slate-300 px-3 py-2 text-xs font-bold text-slate-700">Rejeter</button>{manager&&item.status!=="escalade"&&<button onClick={()=>act(item.id,"escalade")} className="rounded-lg border border-violet-500/30 bg-violet-500/10 px-3 py-2 text-xs font-bold text-violet-700">Escalader</button>}</div>}</article>)}</div></Section><div className="flex items-center justify-between rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-700"><span>Page {pagination.page||page} · {pagination.total||visible.length} dossier(s)</span><div className="flex gap-2"><button disabled={page<=1} onClick={()=>setPage(v=>Math.max(1,v-1))} className="rounded-lg border border-slate-300 px-3 py-1.5 disabled:opacity-40">Précédent</button><button disabled={!pagination.hasNext} onClick={()=>setPage(v=>v+1)} className="rounded-lg border border-slate-300 px-3 py-1.5 disabled:opacity-40">Suivant</button></div></div></div>;
}
